-- Ingredient units become a fixed list (see `unitKeys` in packages/schemas).
-- Known spellings ("grams", "EL", "Esslöffel") are mapped to their key. A unit that is not
-- in the list is dropped, the amount stays, and the old text is added to the note.
-- Generated from `unitSpellings`; do not edit the spelling list by hand.

CREATE TEMP TABLE "unit_spelling" ("spelling" text PRIMARY KEY, "key" text NOT NULL);
--> statement-breakpoint
--> statement-breakpoint
UPDATE "recipe" SET "ingredients" = (
  SELECT COALESCE(
    jsonb_agg(
      CASE
        WHEN jsonb_typeof(item.value -> 'unit') IS DISTINCT FROM 'string' THEN item.value
        WHEN btrim(item.value ->> 'unit') = '' THEN
          jsonb_set(item.value, '{unit}', 'null'::jsonb)
        WHEN found.key IS NOT NULL THEN
          jsonb_set(item.value, '{unit}', to_jsonb(found.key))
        ELSE
          jsonb_set(
            jsonb_set(item.value, '{unit}', 'null'::jsonb),
            '{note}',
            to_jsonb(left(concat_ws(', ', btrim(item.value ->> 'unit'), NULLIF(btrim(item.value ->> 'note'), '')), 300))
          )
      END
      ORDER BY item.position
    ),
    '[]'::jsonb
  )
  FROM jsonb_array_elements("recipe"."ingredients") WITH ORDINALITY AS item(value, position)
  LEFT JOIN "unit_spelling" AS found
    ON found."spelling" = lower(regexp_replace(regexp_replace(btrim(item.value ->> 'unit'), '\s+', ' ', 'g'), '\.$', ''))
)
WHERE jsonb_typeof("ingredients") = 'array';
--> statement-breakpoint
UPDATE "shopping_item" SET "note" = left(
  concat_ws(', ', NULLIF(btrim("unit"), ''), NULLIF(btrim("note"), '')), 300
)
WHERE "unit" IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM "unit_spelling" AS found WHERE found."spelling" = lower(regexp_replace(regexp_replace(btrim("shopping_item"."unit"), '\s+', ' ', 'g'), '\.$', ''))
  );
--> statement-breakpoint
UPDATE "shopping_item" SET "unit" = (
  SELECT found."key" FROM "unit_spelling" AS found
  WHERE found."spelling" = lower(regexp_replace(regexp_replace(btrim("shopping_item"."unit"), '\s+', ' ', 'g'), '\.$', ''))
)
WHERE "unit" IS NOT NULL;
--> statement-breakpoint
DROP TABLE "unit_spelling";
